INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minnesota-fats---pool-legend-usa', 'Genesis', 'Minnesota Fats - Pool Legend (USA)', '1989', 'Sports', 'Data East', '2', 'Sports', 'Professional billiards simulation with a story mode.', 'Defeat rival players to become a pool legend.', 'A realistic 16-bit pool game featuring Minnesota Fats.', 'Minnesota Fats: Pool Legend offers smooth physics and challenging AI. Master the 16-bit cue and climb the ranks in this polished Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miracle-piano-teaching-system-usa', 'Genesis', 'Miracle Piano Teaching System (USA)', '1989', 'Music', 'The Learning Company', '1', 'Educational', 'Educational music software using a specialized keyboard.', 'Learn to play the piano through various 16-bit lessons.', 'A unique and highly ambitious musical teaching tool.', 'Miracle Piano Teaching System turns your Genesis into an instrument. Master real piano skills with 16-bit games and interactive tutorials.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mlbpa-baseball-usa', 'Genesis', 'MLBPA Baseball (USA)', '1993', 'Sports', 'Sega', '2', 'Sports', 'Professional baseball simulation with official player licenses.', 'Win the pennant with real MLB player stats and rosters.', 'A detailed and roster-heavy 16-bit baseball game.', 'MLBPA Baseball features realistic 16-bit animation and deep management. Lead your favorite players to the World Series in this authentic Sega sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mobius-adventures', 'Genesis', 'Mobius Adventures', '2010', 'Platform', 'Fan-made', '1', 'Arcade', 'High-speed platforming with custom level designs.', 'Explore the world of Mobius in a whole new way.', 'A comprehensive fan-made adventure for the Sonic engine.', 'Mobius Adventures features creative 16-bit levels and fresh challenges. Experience a fan-made sequel to the classic Sonic saga on your Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mobius-evolution', 'Genesis', 'Mobius Evolution', '2012', 'Platform', 'Fan-made', '1', 'Arcade', 'High-speed platforming with technical and visual upgrades.', 'Navigate a modernized version of the classic Sonic world.', 'A technical overhaul of the Sonic the Hedgehog engine.', 'Mobius Evolution brings refined 16-bit physics and updated graphics. Experience the evolution of 16-bit speed in this high-quality fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('modern-sonic-in-sonic-2', 'Genesis', 'Modern Sonic in Sonic 2', '2013', 'Platform', 'Fan-made', '1', 'Arcade', 'High-speed platforming with a modern "boost" feel.', 'Blitz through Sonic 2 stages with Modern Sonic''s moveset.', 'A mechanical mod bringing modern moves to 16-bit.', 'Modern Sonic in Sonic 2 introduces the boost and homing attack to West Side Island. Experience a high-energy 16-bit speedrun like never before.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('modern-sonic-in-sonic-3', 'Genesis', 'Modern Sonic In Sonic 3', '2011', 'Platform', 'Fan-made', '1', 'Arcade', 'High-speed platforming with a modern "boost" feel.', 'Blitz through Sonic 3 stages with Modern Sonic''s moveset.', 'A mechanical mod bringing modern moves to 16-bit.', 'Modern Sonic in Sonic 3 adds modern flair to the 16-bit masterpiece. Use homing attacks and air-dashes to conquer Angel Island at top speeds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-usa', 'Genesis', 'Monopoly (USA)', '1992', 'Board', 'Parker Brothers', '4', 'Board Game', 'Digital board game based on the famous property.', 'Bankrupt your opponents by buying and trading property.', 'A faithful 16-bit adaptation of the board game classic.', 'Monopoly on the Genesis features smooth 16-bit animations and customizable rules. Bring the family together for digital property trading on your console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-usa-beta', 'Genesis', 'Monopoly (USA) (Beta)', '1992', 'Board', 'Parker Brothers', '4', 'Board Game', 'Digital board game based on the famous property.', 'Bankrupt your opponents by buying and trading property.', 'A beta development build of the Monopoly game.', 'Explore early board designs and AI logic in the Monopoly Beta. A rare look at the development of this 16-bit board game adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-world-iv-japan', 'Genesis', 'Monster World IV (Japan)', '1994', 'Action-Western', 'Westone', '1', 'Adventure', 'Action-adventure platformer with light RPG elements.', 'Guide Asha and her Pepelogoo to save the four spirits.', 'A late-generation 16-bit masterpiece of art and design.', 'Monster World IV is one of the most beautiful games on the Mega Drive. Experience fluid animation, creative puzzles, and a heartwarming story in this quintessential Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-world-iv-japan-en-by-dejap+demiforce-v102', 'Genesis', 'Monster World IV (Japan) [En by DeJap+Demiforce v1.02]', '1994', 'Action-Western', 'Westone', '1', 'Adventure', 'Action-adventure platformer with light RPG elements.', 'Guide Asha and her Pepelogoo to save the four spirits.', 'A high-quality English fan translation by DeJap and Demiforce.', 'Monster World IV (English Translation) finally makes this Japanese gem accessible. Experience the 16-bit charm and deep adventure mechanics with full English text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-world-iv-japan-en-by-dejap+demiforce+shion-v22', 'Genesis', 'Monster World IV (Japan) [En by DeJap+Demiforce+Shion v2.2]', '1994', 'Action-Western', 'Westone', '1', 'Adventure', 'Action-adventure platformer with light RPG elements.', 'Guide Asha and her Pepelogoo to save the four spirits.', 'The updated v2.2 English translation for the best experience.', 'Monster World IV (v2.2 Translation) offers the most polished English script available. Master the 16-bit platforming and spirit-saving quest on your Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monsters-inc-god-mode', 'Genesis', 'Monster''s Inc. God Mode', '2015', 'Action', 'Fan-made', '1', 'Arcade', 'Side-scrolling platformer with invincibility and infinite life.', 'Navigate Monstropolis without fear of taking damage.', 'A "God Mode" modification for the Pixar-based adventure.', 'Monsters Inc. God Mode lets you explore the 16-bit world of Mike and Sulley stress-free. Perfect for younger players or those who want to see every secret without the challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-world', 'Genesis', 'Mortal Kombat (World)', '1992', 'Fighting', 'Midway', '2', 'Fighting', 'One-on-one fighting game with digitized sprites and fatalities.', 'Defeat Shang Tsung in the tournament to save Earthrealm.', 'The legendary 16-bit port that featured the famous blood code.', 'Mortal Kombat on the Genesis is a piece of gaming history. Master the "DULLARD" code to unlock the full arcade experience and visceral combat on your console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-world-v11', 'Genesis', 'Mortal Kombat (World) (v1.1)', '1992', 'Fighting', 'Midway', '2', 'Fighting', 'One-on-one fighting game with digitized sprites and fatalities.', 'Defeat Shang Tsung in the tournament to save Earthrealm.', 'An updated revision (v1.1) of the 16-bit fighting hit.', 'Mortal Kombat on the Genesis remains a cornerstone of the genre. Experience the refined 16-bit combat and iconic fatalities in this polished Sega port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-world-hack-by-hiro1112-v20060806-blood+translation-fix', 'Genesis', 'Mortal Kombat (World) [Hack by Hiro1112 v20060806] (Blood+Translation Fix)', '1992', 'Fighting', 'Midway', '2', 'Fighting', 'One-on-one fighting game with blood and translation fixes.', 'Conquer the tournament with arcade-accurate text and gore.', 'A technical fan-fix for the original 16-bit port.', 'Mortal Kombat (Hiro1112 Hack) restores the grit and polish of the arcade original. Enjoy a more authentic 16-bit experience with corrected text and visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-1-boss-hack-47-fix-by-worm', 'Genesis', 'Mortal Kombat 1 (BOSS HACK) 4.7 fix by Worm', '2009', 'Fighting', 'Fan-made', '2', 'Fighting', 'One-on-one fighting game allowing play as boss characters.', 'Dominate the tournament as Goro or Shang Tsung.', 'A specialized hack enabling boss play in Mortal Kombat 1.', 'Mortal Kombat 1 Boss Hack (v4.7) lets you use the world''s most feared fighters. Master Goro’s strength in this unique and balanced 16-bit modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-1-boss-hack-beta', 'Genesis', 'Mortal Kombat 1 Boss Hack Beta', '2009', 'Fighting', 'Fan-made', '2', 'Fighting', 'One-on-one fighting game allowing play as boss characters.', 'Test the early mechanics of playing as the game''s bosses.', 'A beta version of the Boss Hack project.', 'Peek at the development of playable bosses in the Mortal Kombat 1 Boss Hack Beta. A rare look at how fans opened the 16-bit roster to Goro and more.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-3-europe', 'Genesis', 'Mortal Kombat 3 (Europe)', '1995', 'Fighting', 'Midway', '2', 'Fighting', 'One-on-one fighting game with a run button and dial-a-combos.', 'Stop Shao Kahn’s invasion of Earth in this fast-paced sequel.', 'The European release of the third MK blockbuster.', 'Mortal Kombat 3 introduces incredible 16-bit speed and complexity. Master the combo system and use the new "Run" mechanic to crush your rivals on Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-3-usa', 'Genesis', 'Mortal Kombat 3 (USA)', '1995', 'Fighting', 'Midway', '2', 'Fighting', 'One-on-one fighting game with a run button and dial-a-combos.', 'Stop Shao Kahn’s invasion of Earth in this fast-paced sequel.', 'The North American release of the high-octane fighter.', 'Mortal Kombat 3 introduces incredible 16-bit speed and complexity. Master the combo system and use the new "Run" mechanic to crush your rivals on Genesis.');
