INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-arcade-edition-enhanced-v17', 'Genesis', 'Mortal Kombat Arcade Edition Enhanced v1.7', '2019', 'Fighting', 'Fan-made', '2', 'Arcade', 'One-on-one fighting game with arcade-accurate colors and audio.', 'Experience Mortal Kombat 1 with enhanced technical polish.', 'A technical overhaul (v1.7) for the Genesis port.', 'Mortal Kombat Arcade Edition Enhanced v1.7 provides the most balanced 16-bit gameplay yet. Experience arcade-style frames and speed on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-arcade-edition-enhanced-v18', 'Genesis', 'Mortal Kombat Arcade Edition Enhanced v1.8', '2020', 'Fighting', 'Fan-made', '2', 'Arcade', 'One-on-one fighting game with arcade-accurate colors and audio.', 'Experience Mortal Kombat 1 with enhanced technical polish.', 'The ultimate technical overhaul (v1.8) for the Genesis port.', 'Mortal Kombat Arcade Edition Enhanced v1.8 is the pinnacle of the MK1 mods. Experience near arcade-perfect 16-bit visuals and audio on the Sega hardware.');
