INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-ii-world', 'Genesis', 'Mortal Kombat II (World)', '1993', 'Fighting', 'Midway', '2', 'Fighting', 'One-on-one fighting game with an expanded roster and stages.', 'Defeat Shao Kahn in the Outworld tournament.', 'The massive and highly-rated 16-bit sequel.', 'Mortal Kombat II is widely considered the best of the trilogy. Master the 16-bit fatalities and discover hidden characters in this quintessential Sega hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-ii-world-hack-by-smoke-v070-~mortal-kombat-ii-unlimited', 'Genesis', 'Mortal Kombat II (World) [Hack by Smoke v0.70] (~Mortal Kombat II Unlimited)', '1993', 'Fighting', 'Midway', '2', 'Fighting', 'One-on-one fighting game with massive roster expansion.', 'Play as every character from the first three games in MK2.', 'A legendary hack that expands the roster to dozens of fighters.', 'Mortal Kombat II Unlimited is a 16-bit marvel. Featuring new moves, more characters, and extra stages, it is the ultimate MK experience for the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-ii-unlimited---enhanced-colors', 'Genesis', 'Mortal Kombat II Unlimited - Enhanced Colors', '1994', 'Fighting', 'Fan-made', '2', 'Fighting', 'One-on-one fighting game with improved 16-bit visuals.', 'Conquer the MK2 Unlimited mod with a richer color palette.', 'A visual enhancement of the famous Unlimited hack.', 'Mortal Kombat II Unlimited: Enhanced Colors brings vibrant life to the 16-bit carnage. Experience the massive roster with improved arcade-style aesthetics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-ii-unlimited-dark-edition', 'Genesis', 'Mortal Kombat II Unlimited Dark Edition', '1994', 'Fighting', 'Fan-made', '2', 'Fighting', 'One-on-one fighting game with a dark, atmospheric aesthetic.', 'Battle through a grittier version of the Outworld tournament.', 'A visual "Dark Edition" of the Unlimited project.', 'Mortal Kombat II Unlimited: Dark Edition offers a moody and intense 16-bit experience. Experience the ultimate roster with a unique, shadowy visual style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-revelations', 'Genesis', 'Mortal Kombat Revelations', '2011', 'Fighting', 'Fan-made', '2', 'Fighting', 'One-on-one fighting game with characters from the entire series.', 'Win the ultimate tournament in this comprehensive fan project.', 'A massive fan-made crossover brawler for the Genesis.', 'Mortal Kombat Revelations brings a modern "Armageddon" feel to the 16-bit era. Enjoy dozens of characters and custom stages in this impressive Sega mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('movie-sonic-in-sonic-3', 'Genesis', 'Movie Sonic in Sonic 3', '2013', 'Platform', 'Fan-made', '1', 'Arcade', 'High-speed platforming featuring the film-inspired hedgehog.', 'Conquer Sonic 3 with the movie''s blue blur aesthetic.', 'A visual character-swap mod for the Sonic 3 engine.', 'Movie Sonic in Sonic 3 brings the Hollywood star to the 16-bit masterpiece. Enjoy custom sprites based on the film in this stylish Sega modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-needlemouse', 'Genesis', 'Mr. Needlemouse', '2013', 'Platform', 'Fan-made', '1', 'Arcade', 'High-speed platforming featuring the original prototype mascot.', 'Explore Sonic 1 as the character that almost was: Needlemouse.', 'A historical and creative character-swap mod.', 'Mr. Needlemouse brings the early Sega concept to life on the 16-bit hardware. Experience the origin story with a unique and nostalgic twist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-nutz-europe', 'Genesis', 'Mr. Nutz (Europe)', '1994', 'Platform', 'Ocean', '1', 'Platformer', 'Side-scrolling platformer featuring a squirrel with a hat.', 'Save the world and defeat the evil Mr. Blizzard.', 'A colorful and technically impressive European platformer.', 'Mr. Nutz features incredible 16-bit art and large, creative levels. Master the tail-whip and jump-attacks in this polished and charming Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-usa-europe', 'Genesis', 'Ms. Pac-Man (USA, Europe)', '1991', 'Arcade', 'Namco', '2', 'Arcade', 'Classic arcade maze-navigation with improved speed.', 'Clear all the dots in the maze while avoiding the ghosts.', 'The definitive 16-bit version of the arcade classic.', 'Ms. Pac-Man on the Genesis is widely regarded as the best home port. Enjoy four unique mazes and smooth 16-bit gameplay in this timeless arcade hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mugen-senshi-valis-japan', 'Genesis', 'Mugen Senshi Valis (Japan)', '1987', 'Action', 'Telenet Japan', '1', 'Action', 'Side-scrolling action platformer with cinematic cutscenes.', 'Defeat the Dark World forces to save the kingdom.', 'The first entry in the legendary Valis series.', 'Mugen Senshi Valis features an iconic anime aesthetic and challenging combat. Experience the 16-bit origins of Yuko''s quest on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('muhammad-ali-heavyweight-boxing-europe', 'Genesis', 'Muhammad Ali Heavyweight Boxing (Europe)', '1993', 'Sports', 'Reebok Interactive', '2', 'Sports', 'One-on-one boxing simulation with an isometric perspective.', 'Rise through the ranks as "The Greatest" to win the title.', 'A realistic and strategic 16-bit boxing game.', 'Muhammad Ali Heavyweight Boxing features large sprites and tactical combat. Master the 16-bit jab and shuffle in this definitive Sega sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('muhammad-ali-heavyweight-boxing-usa', 'Genesis', 'Muhammad Ali Heavyweight Boxing (USA)', '1993', 'Sports', 'Reebok Interactive', '2', 'Sports', 'One-on-one boxing simulation with an isometric perspective.', 'Rise through the ranks as "The Greatest" to win the title.', 'The North American release of the Muhammad Ali sim.', 'Muhammad Ali Heavyweight Boxing features large sprites and tactical combat. Master the 16-bit jab and shuffle in this definitive Sega sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('muhammad-ali-heavyweight-boxing-usa-beta', 'Genesis', 'Muhammad Ali Heavyweight Boxing (USA) (Beta)', '1993', 'Sports', 'Reebok Interactive', '2', 'Sports', 'One-on-one boxing simulation with an isometric perspective.', 'Rise through the ranks as "The Greatest" to win the title.', 'A beta development build of the Ali boxing game.', 'Peek into the tuning of 16-bit boxing physics with the Muhammad Ali Beta. A rare look at the development of this strategic Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mulan-china-unl', 'Genesis', 'Mulan (China) (Unl)', '1998', 'Platform', 'Unlicensed', '1', 'Platformer', 'Side-scrolling platformer based on the legend of Mulan.', 'Defeat the invading forces and bring honor to your family.', 'A rare and colorful unlicensed 16-bit Disney adaptation.', 'Mulan (Unl) offers a unique unlicensed take on the legendary warrior. Navigate 16-bit ancient China with custom sprites and challenging platforming on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('musha---metallic-uniframe-super-hybrid-armor-usa', 'Genesis', 'MUSHA - Metallic Uniframe Super Hybrid Armor (USA)', '1990', 'Shooter', 'Compile', '1', 'Shoot ''em Up', 'Vertical-scrolling shoot ''em up with a mecha theme.', 'Pilot the MUSHA unit to destroy the rogue supercomputer Dire 51.', 'One of the most acclaimed and valuable shmups on the system.', 'MUSHA delivers blistering 16-bit speed and a legendary soundtrack. Master the customizable weapon system and survive intense mechanical warfare in this Compile masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('musha-aleste---full-metal-fighter-ellinor-japan', 'Genesis', 'Musha Aleste - Full Metal Fighter Ellinor (Japan)', '1990', 'Shooter', 'Compile', '1', 'Shoot ''em Up', 'Vertical-scrolling shoot ''em up with a mecha theme.', 'Pilot the Aleste unit to stop the bio-mechanical invasion.', 'The Japanese Mega Drive version of the legendary MUSHA.', 'Musha Aleste is the pinnacle of 16-bit shooting action. Experience fluid sprite work and high-octane combat in this essential Japanese Mega Drive classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mutant-league-football-japan', 'Genesis', 'Mutant League Football (Japan)', '1993', 'Sports', 'Electronic Arts', '2', 'Sports', 'Combat-heavy American football with hazards and weapons.', 'Win the Mutant Bowl by outscoring or killing the opposition.', 'A brutal and hilarious post-apocalyptic sports game.', 'Mutant League Football features landmines, fire pits, and deadly tackles. Lead your team of monsters to 16-bit glory in this violent cult classic from EA.');
