INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mutant-league-hockey-usa-europe', 'Genesis', 'Mutant League Hockey (USA, Europe)', '1994', 'Sports', 'Electronic Arts', '2', 'Sports', 'Combat-heavy ice hockey with weapons and traps.', 'Survive the rink and win the Monster Cup.', 'A violent and fast-paced 16-bit hockey spinoff.', 'Mutant League Hockey brings the carnage to the ice. Battle through 16-bit hazards and use weapons to incapacitate rivals in this fan-favorite Sega sports title.');
