INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystical-fighter-usa', 'Genesis', 'Mystical Fighter (USA)', '1992', 'Action', 'KID', '2', 'Fighting', 'Side-scrolling beat ''em up with a Kabuki/mythological theme.', 'Defeat the mechanical demons across ancient Japan.', 'A stylish and high-energy 16-bit brawler (Maou Renjishi).', 'Mystical Fighter features unique 16-bit grappling and cinematic special moves. Battle through mythic stages in this polished and distinctive Sega brawler.');
