INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-quarterback-club-96-usa-europe', 'Genesis', 'NFL Quarterback Club 96 (USA, Europe)', '1996', 'Sports', 'Iguana Entertainment', '2', 'Sports', 'Multi-event football simulation with updated 1996 features.', 'Lead your NFL team to glory with refined 16-bit controls.', 'The expanded sequel to the Quarterback Club series.', 'NFL Quarterback Club 96 offers improved 16-bit graphics and more tactical options. Experience professional gridiron depth on your Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-sports-talk-football-93-starring-joe-montana-usa-europe', 'Genesis', 'NFL Sports Talk Football ''93 Starring Joe Montana (USA, Europe)', '1993', 'Sports', 'Electronic Arts', '2', 'Sports', 'Isometric football with non-stop voice commentary.', 'Master the gridiron with 1993 rosters and live speech.', 'A foundational "Sports Talk" football experience.', 'NFL Sports Talk Football ''93 features constant 16-bit commentary and deep plays. Experience the innovation that defined Sega''s sports legacy.');
