INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('omg-the-red-rings', 'Genesis', 'OMG THE RED RINGS', '2023', 'Platformer', 'Fan-made', '1', 'Platform', 'High-speed platforming with a custom collectible focus.', 'Collect the elusive Red Rings in this Sonic modification.', 'A "Red Ring" centered mod for the Sonic engine.', 'OMG THE RED RINGS turns the classic 16-bit levels into a treasure hunt. Find every hidden ring in this creative and challenging Sega fan project.');
