INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('overpowered-sonic-the-hedgehog-2', 'Genesis', 'Overpowered Sonic The Hedgehog 2', '2020', 'Platformer', 'Fan-made', '1', 'Platform', 'High-speed platforming with god-like speed and power.', 'Blitz through levels with an "overpowered" 16-bit Sonic.', 'A mechanical mod for the Sonic 2 engine.', 'Overpowered Sonic 2 removes all limits on the Blue Blur. Experience 16-bit speed at a game-breaking level in this fun and chaotic Sega fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-attack-usa', 'Genesis', 'Pac-Attack (USA)', '1993', 'Puzzle', 'Sega', '2', 'Puzzle', 'Falling-block puzzle game with ghosts and power-ups.', 'Match blocks and clear ghosts using Pac-Man’s movement.', 'A colorful and addictive 16-bit puzzle spin-off.', 'Pac-Attack combines classic Pac-Man elements with Tetris-style logic. Master the 16-bit puzzle boards and clear the ghosts in this fun Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-2---the-arcade-games', 'Genesis', 'Pac-Man 2 - The Arcade Games', '1993', 'Action', 'Namco', '1', 'Action', 'Classic arcade maze-navigation.', 'Clear all dots while avoiding ghosts in classic 16-bit ports.', 'A hidden bonus compilation of original Pac-Man hits.', 'Pac-Man 2: The Arcade Games features faithful 16-bit ports of Pac-Man and Ms. Pac-Man. Relive the arcade glory with perfect controls on your Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-2---the-new-adventures-usa', 'Genesis', 'Pac-Man 2 - The New Adventures (USA)', '1994', 'Adventure', 'Namco', '1', 'Adventure', 'Point-and-click adventure with physics-based interaction.', 'Guide a temperamental Pac-Man through a cartoon world.', 'A unique and experimental interactive cartoon adventure.', 'Pac-Man 2: The New Adventures breaks the mold with 16-bit physics-based puzzles. Use a slingshot to influence Pac-Man’s mood and solve his quest on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-mania-usa-europe', 'Genesis', 'Pac-Mania (USA, Europe)', '1991', 'Action', 'Namco', '1', 'Arcade', 'Isometric maze-navigation with a jumping mechanic.', 'Clear dots and jump over ghosts in a 3D-style world.', 'A vibrant and bouncy 16-bit evolution of Pac-Man.', 'Pac-Mania brings the series into the third dimension with 16-bit sprite scaling. Master the jump and clear the Lego-like worlds in this classic Sega port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-mania-arcade-style-tilesspritescolors', 'Genesis', 'Pac-Mania arcade style tiles/sprites/colors', '2022', 'Graphics', 'Fan-made', '1', 'Visual', 'Isometric maze-navigation with enhanced visuals.', 'Clear dots with a focus on arcade-accurate colors.', 'A visual and aesthetic mod for the Pac-Mania engine.', 'Pac-Mania arcade style tiles/sprites/colors restores the coin-op look to the Genesis. Enjoy the ultimate 16-bit visual polish in this community-driven modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachinko-kuunyan-japan', 'Genesis', 'Pachinko Kuunyan (Japan)', '1994', 'Pachinko', 'Sega', '1', 'Casino', 'Pachinko simulation with a colorful anime theme.', 'Win big on the virtual pinball machines to unlock secrets.', 'A quirky and bright Japanese Pachinko sim.', 'Pachinko Kuunyan offers a relaxing and colorful 16-bit gambling experience. Master the machine''s physics on the Japanese Mega Drive.');
