INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pagemaster-the-europe', 'Genesis', 'Pagemaster, The (Europe)', '1994', 'Platformer', 'Probe Software', '1', 'Platform', 'Side-scrolling platformer based on the fantasy film.', 'Navigate literary worlds to escape the library.', 'A magical 16-bit adventure through classic stories.', 'The Pagemaster features worlds based on Horror, Adventure, and Fantasy. Master the 16-bit platforming and solve puzzles in this cinematic Sega title.');
