INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pana-der-hejhog', 'Genesis', 'Pana Der Hejhog', '2020', 'Platformer', 'Fan-made', '1', 'Platform', 'High-speed platforming featuring a bizarre meme hero.', 'Navigate custom levels as the infamous Pana Der Hejhog.', 'A humorous and mechanically sound Sonic modification.', 'Pana Der Hejhog offers a quirky take on 16-bit speed. Explore unique zones with custom sprites in this legendary and funny Sega community project.');
