INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ragnacenty-korea', 'Genesis', 'Ragnacenty (Korea)', '1994', 'Action', 'Sega', '1', 'Action RPG', 'Action RPG with an animal-partner system.', 'Stop the monsters and discover the truth of the world.', 'The Korean version of the masterpiece Crusader of Centy.', 'Ragnacenty is a top-tier 16-bit Action RPG. Use the unique animal-companion system to solve puzzles and explore a vibrant world in this Mega Drive gem.');
