INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rambo-iii-world', 'Genesis', 'Rambo III (World)', '1989', 'Action', 'Ocean Software', '2', 'Run and Gun', 'Top-down action-shooter based on the film.', 'Rescue Colonel Trautman from a Soviet fortress.', 'A fast-paced and explosive 16-bit combat game.', 'Rambo III features various weapon types and intense boss fights. Experience the 16-bit jungle warfare and stealth missions in this classic Sega title.');
