INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rampart-usa', 'Genesis', 'Rampart (USA)', '1991', 'Strategy', 'Atari Games', '2', 'Real-time Strategy', 'Strategy and puzzle-action hybrid.', 'Build fortifications and destroy enemy ships with cannons.', 'A unique 16-bit port of the Atari arcade hit.', 'Rampart combines tetris-style building with tactical combat. Defend your castle in this addictive and competitive 16-bit Sega strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ranger-x-europe', 'Genesis', 'Ranger-X (Europe)', '1993', 'Action', 'Sega', '1', 'Sci-Fi Shooter', 'Side-scrolling run-and-gun with 360-degree aiming.', 'Pilot the heavy armor suit to stop the Rahu invasion.', 'A technical masterpiece of 16-bit parallax and speed.', 'Ranger-X is one of the most visually impressive games on the system. Master the unique dual-control system and explore massive levels on your Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ranger-x-usa', 'Genesis', 'Ranger-X (USA)', '1993', 'Action', 'Sega', '1', 'Sci-Fi Shooter', 'Side-scrolling run-and-gun with 360-degree aiming.', 'Pilot the heavy armor suit to stop the Rahu invasion.', 'The North American release of the technical action hit.', 'Ranger-X features incredible backgrounds and fluid mechanical action. Experience the peak of 16-bit technical design in this essential Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ransei-no-hasha-japan', 'Genesis', 'Ransei no Hasha (Japan)', '1993', 'Strategy', 'Sega', '1', 'Turn-based Strategy', 'Grand strategy simulation set in feudal Japan.', 'Conquer the provinces to become the supreme ruler.', 'A deep historical strategy game (Conqueror of the World).', 'Ransei no Hasha features complex 16-bit management and tactical warfare. Lead your clan to victory on the Japanese Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rastan-saga-ii-japan', 'Genesis', 'Rastan Saga II (Japan)', '1992', 'Action', 'Taito', '2', 'Side-scrolling Action', 'Side-scrolling hack-and-slash action.', 'Battle through mythic lands to defeat the evil wizard.', 'A large-sprite 16-bit sequel to the arcade original.', 'Rastan Saga II offers intense sword-fighting and huge bosses. Experience the dark fantasy atmosphere and 16-bit combat on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rastan-saga-ii-usa', 'Genesis', 'Rastan Saga II (USA)', '1992', 'Action', 'Taito', '2', 'Side-scrolling Action', 'Side-scrolling hack-and-slash action.', 'Battle through mythic lands to defeat the evil wizard.', 'The North American release of the fantasy brawler.', 'Rastan Saga II (Nastar Warrior) features challenging combat and iconic 16-bit artwork. Conquer the mythic beasts in this high-energy Sega title.');
