INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ristar-aug-26-1994-prototype', 'Genesis', 'Ristar (Aug 26, 1994 prototype)', '1994', 'Platform', 'Sonic Team', '1', 'Action Platformer', 'Side-scrolling platformer with grabbing mechanics.', 'Explore the refining stages of the game''s mechanics.', 'A developmental prototype from late August 1994.', 'Ristar (Aug 26 Prototype) features near-final mechanics but with distinct 16-bit debug options. Trace the final steps of Sega''s creative design process.');
