INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ristar-usa-europe-august-1994', 'Genesis', 'Ristar (USA, Europe) (August 1994)', '1995', 'Platform', 'Sonic Team', '1', 'Action Platformer', 'Side-scrolling platformer with grabbing mechanics.', 'Save the solar system using your elastic arms.', 'The first retail-ready build for Western regions.', 'Ristar features incredible 16-bit color palettes and creative boss fights. Experience the height of Sega''s platforming innovation on your Genesis.');
