INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-rash-usa-europe', 'Genesis', 'Road Rash (USA, Europe)', '1991', 'Racing', 'Electronic Arts', '2', 'Arcade Racing', 'Combat-racing on motorcycles with melee weapons.', 'Win the underground circuit while dodging traffic and police.', 'The gritty and high-octane 16-bit racing debut.', 'Road Rash combines speed with visceral combat. Use clubs and chains to knock rivals off their bikes in this rebellious Sega classic.');
